Item.template:
import { method, itemType as itemTypeMetadata } from 'metadata';
import { xmlToODataJson, type Toolbar } from 'core';
import { serialization } from 'store';
import { buildItemTypeColumnLayout } from '../Modules/cui/plugins/adaptGridHeader';
import type { LayoutData } from '../Modules/store/storeTypes';
import type {
	ItemTypeProperty,
	ExtendedItemTypeXProperty,
	RelationshipType
} from '../Modules/metadata/metadataTypes';
import type { toolbarItems } from '../Modules/components/toolbarTypes';
import type { Options, BaseInitHandlerReturnType } from '../Modules/cui/cuiTypes';

type InitHandlerReturnType = Partial<toolbarItems> & BaseInitHandlerReturnType;

export function $method_name(
	control: Toolbar,
	target: toolbarItems,
	options: Options<'SearchView'> | Options<'RelationshipsView'>
): InitHandlerReturnType {
	$method_code;
}
